csui.define('d2/overrides/csui/utils/commands/browse',['require', 'nuc/lib/jquery', 'nuc/lib/underscore',
  'csui/utils/commandhelper',
  'csui/utils/commands/browse',
  'd2/utils/constants'
], function (require, $, _, CommandHelper, Browse, constants) {
  'use strict';

  var oldEnabled = Browse.prototype.enabled;

  Browse.prototype.enabled = function (status/*, options*/) {
    var enabled = oldEnabled.apply(this, arguments);
    var node = CommandHelper.getJustOneNode(status);
    return enabled || (status.defaultAction
      && _.contains([constants.Types.DOCUMENT, constants.Types.EMAIL], node.get('type')));
  };

});
