csui.define('d2/server.adaptors/models/node.ancestors.mixin',[
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'nuc/utils/url',
  'csui/utils/contexts/factories/next.node',
  'dctmw/server.adaptors/converters/node',
  'd2/utils/contexts/context.controller',
  'dctmw/utils/rest.resources',
  'd2/utils/rest.linkrels',
  'dctmw/utils/authenticators/session',
  'd2/utils/node.utils',
  'dctmw/utils/utils',
  'd2/utils/widgets.utils',
  'd2/utils/constants',
  'd2/utils/contexts/factories/node.navigation',
  'i18n!d2/server.adaptors/models/impl/nls/lang'
], function ($, _, Url, NextNodeModelFactory, nodeConverter, D2ContextController, RestResources, RestLinkrels, Session ,nodeUtils, utils, widgetUtils, constants,
             NodeNavigationCollctionFactory, lang) {
  'use strict';

  return {

    mixin: function (prototype) {
      var superSyncMethod = prototype.sync;

      return _.extend(prototype, {
        makeServerAdaptor: function (/*options*/) {
          return this;
        },

        url: function () {
          var url = RestLinkrels.getLink(RestResources.getCurrentRepository().get('links'), RestLinkrels.OBJECTS_LOCATIONS);
          return Url.appendQuery(url, Url.combineQueryString({'object-ids': this.node.get('id')}));
        },

        parse: function (response/*, options*/) {
          var ancestors = [], pathIds = [], pathNames = [], i, index, bcRoot,
            nodeId = this.node.get('id'),
            config = response.specialNodeConfig,
            pathIdsStr, pathNamesStr,
            nodeNavigationCollection = this.connector.context && this.connector.context.getCollection(NodeNavigationCollctionFactory);

          if (!this.root || _.isEmpty(this.root)) {
            bcRoot = D2ContextController.getBreadcrumbRoot();
            this.root = (bcRoot && bcRoot.root) || {};
            this.rootSubId = (bcRoot && bcRoot.rootSubId) || undefined;
          }

          if (response && _.isArray(response.entries) && response.entries.length > 0) {
            var entry = response.entries[0].content;
            var locationObj = null;
            const namedSessionStorage = utils.getSessionStore('navigatedFromDoclist');
            if (entry.properties && entry.properties.length > 1) {
              if (nodeNavigationCollection && nodeNavigationCollection.length > 0) {
                //mutiple location paths available first calculate the actual selected path based on the node navigation collection
                // In case of linked folder in the path there can be path element change anywhere in the path
                // so its important to get the exact selected Path
                var nodePath = [],
                    widgetName = config.objectName,
                    widgetAncestorInfo = widgetUtils.getAncestorInfo(widgetName);
                if(widgetAncestorInfo?.ancestors && namedSessionStorage.get('navigatedFromDoclist')){
                  this.getNodePath(widgetAncestorInfo?.ancestors, nodePath)
                }
                else{
                  this.getNodePath(nodeNavigationCollection, nodePath)
                }
                var nodePathString = '/' + (nodePath.join('/'));

                // DTWO-120050 Fix
                // When startpath is set to folders below cabinets level, then node navigation collection starts from startpath
                // But the location.ancestor_id_path starts from repository
                // Hence strict equals comparison will fail and locationObj will be undefined and take the first entry by default
                // Fix: Check if location.ancestor_id_path endsWith nodePathString formed from node navigation collection

                // TODO: DTWO-112434 - Breadcrumbs Issue for homecabinet
                // Revisit this file, open node perspective(setting is_home_cabinet flag) codes etc for handling homecabinet
                // Our existing nodeUtils method to getHomeCabinet returns only id for the homecabinet
                // Have to see if we can handle with the id alone or if REST can send another attribute with full path for homecabinet

                if (config.startingPath) {
                  locationObj = _.find(entry.properties, function (location) {
                    return location.ancestor_id_path && location.ancestor_id_path.endsWith(nodePathString);
                  }.bind(this));
                } else {
                  locationObj = _.find(entry.properties, function (location) {
                    return location.ancestor_id_path && _.isEqual(location.ancestor_id_path, nodePathString);
                  }.bind(this));
                }
              }
              // Fix for VE-4810317 Issue 1.Added fallback logic for restoring the location object which matches with the node parent before setting to zero index of locations.
              // Since order of items in "folder_id" in objects API and location in objects-locations API are not same. To maintain the last parity between node parent and object location,
              // resetting the locationObj with location information which was matching the parent.
              if (!locationObj) {
                locationObj = _.find(entry.properties, function (location) {
                  return this.node.parent && location.ancestor_id_path && location.ancestor_id_path.endsWith(this.node.parent.get('id'));
                }.bind(this));
              }
            }

            if (!locationObj) {
              if (entry.properties) {
                locationObj = entry.properties[0];
              } else {
                if (!this.node.has('type')) {
                  nodeConverter.setNodeType(this.node.attributes);
                }
                // Distinguish between cabinets and hidden folders as both will not have properties
                if (this.node.get('type') === constants.Types.CABINET) {
                  locationObj = {ancestor_id_path: entry.id, r_folder_path: entry.name};
                } else {
                  var path = '/' + constants.HiddenItems.ID + '/';
                  locationObj = {ancestor_id_path: path + entry.id, r_folder_path: path + entry.name};
                }
              }
            }
            if(namedSessionStorage.get('navigatedFromDoclist')){
              namedSessionStorage.remove('navigatedFromDoclist');
            }
            pathIdsStr = locationObj.ancestor_id_path;
            if (pathIdsStr.indexOf('/') === 0) {
              pathIdsStr = pathIdsStr.substr(1);
            }
            pathNamesStr = locationObj.r_folder_path;
            if (pathNamesStr.indexOf('/') === 0) {
              pathNamesStr = pathNamesStr.substr(1);
            }

            pathIds = pathIdsStr.split('/');
            pathNames = pathNamesStr.split('/');
          }

          // Set the root
          this._setRootForNode(config, pathIds);

          if (utils.isMobile()) {
            this._resetRootForMobile(config, pathIds, pathNames);
          }

          // Push the current folder into ancestors
          // If <repo>/<cabinet>/F1/F2 and we drill into F2, path should include F2 which will not be in rest response
          if (!nodeConverter.isNonDCTMNode(this.node) && this.node.get('_is_home_cabinet') !== true) {
            // Pick from node. This is for server-side performance.
            if (pathIds.indexOf(nodeId) === -1) {
              pathIds.push(nodeId);
              pathNames.push(this.node.get('name') || (_.isArray(response.entries) && response.entries[0].content && response.entries[0].content['name']) || '');
            }
            if (!this.rootSubId) {
              if (this.root.id === constants.NodeId.FAVORITES || nodeConverter.isDQLNode(this.root.id)) {
                this.rootSubId = nodeId;
              }
            }
          }

          if (this.rootSubId && pathIds[0] !== constants.HiddenItems.ID) {
            index = pathIds.indexOf(this.rootSubId);
            if (index === -1) {
              this.rootSubId = nodeId;
              index = pathIds.indexOf(this.rootSubId);
            }
            if (index !== -1) {
              pathIds = pathIds.slice(index);
              pathNames = pathNames.slice(index);
            }
          }

          index = pathIds.indexOf(config.startingPath);
          if (index !== -1) {
            pathIds = pathIds.slice(index);
            pathNames = pathNames.slice(index);
          }

          // If Home cabinet is a folder, then ensure that path gets trimmed to exclude items above it
          if (this.root._is_home_cabinet) {
            index = pathIds.indexOf(this.root.id);
            if (index !== -1) {
              pathIds = pathIds.slice(index + 1);
              pathNames = pathNames.slice(index + 1);
            }
          }

          for (i = 0; i < pathIds.length; i++) {
            if (pathIds[i] === constants.HiddenItems.ID && pathNames[i] === constants.HiddenItems.ID) {
              pathNames[i] = constants.HiddenItems.NAME;
            }
            var objectName = pathNames[i];
            if (this.options.isTargetBrowse && !config.treeEnabled && config.homeCabinetEnabled && pathIds[i] === nodeUtils.getHomeCabinetId()) {
              var homeNode = this.getHomeCabineNode();
              objectName = homeNode.name;
            }
            ancestors.push({r_object_id: pathIds[i], object_name: objectName});
          }

          ancestors = nodeConverter.convertAncestors(ancestors);

          if (pathIds[0] === constants.HiddenItems.ID) {
            ancestors.splice(0, 0, this.root);
          } else {
            if (this.root.id === constants.NodeId.REPOSITORY || nodeConverter.isDQLNode(this.root.id)) {
              ancestors.splice(0, 0, this.root);
            }
            // Home/Favorites should be under Starting path node (if tree is not enabled)
            if (this.root.id === constants.NodeId.FAVORITES || this.root._is_home_cabinet) {
              ancestors.splice(0, 0, this.root);
              if (!config.treeEnabled) {
                ancestors.splice(0, 0, this.startPathNode || nodeUtils.createSpecialNode(constants.NodeId.REPOSITORY));
              }
            }
          }


          //In Mobile Since there is no breadcrumbs, root will not be updated every time. So avoid setting root
          if (!utils.isMobile() && !this.options.isTargetBrowse) {
            D2ContextController.setBreadcrumbRoot({
              root: _.pick(this.root, 'id', 'name', 'type', '_is_home_cabinet'),
              rootSubId: this.rootSubId
            });
          }
          return ancestors;
        },

        // Override sync method to avoid making unnecessary call for 'repository' node as it does not have any ancestor
        sync: function (method, model, options) {
          var me = this,
            args = arguments;

          if (method === 'read') {
            var deferred = $.Deferred(),
                refresherOptions = _.pick(options, 'ignoreHttp403', 'reload', 'skipSWCache');

            me.node.ensureFetched(refresherOptions).done(function () {
              var spcCfg = nodeUtils.getSpecialNodeConfig(me.node),
                startNodePromise;
              // Ensure that startPathNode is populated if startingPath config is there
              if (!me.startPathNode && !spcCfg.isDqlRoot && spcCfg.startingPath !== constants.NodeId.REPOSITORY) {
                startNodePromise = me._fetchStartPathNode(spcCfg);
              } else {
                startNodePromise = $.Deferred().resolve().promise();
              }

              startNodePromise.done(function () {
                if (nodeConverter.isNonDCTMNode(me.node) || me.node.get('_is_home_cabinet') === true) {
                  me.trigger('request', me, {}, options);
                  setTimeout(function () {
                    options.success.call(options.context, {entries: [], specialNodeConfig: spcCfg}, 'success', {});
                    deferred.resolve(me);
                  });
                } else {
                  var oldSuccess = options.success;
                  options.success = function (response, status, xhr) {
                    response = response || {};
                    response.specialNodeConfig = spcCfg;
                    oldSuccess.call(options.context, response, status, xhr);
                    deferred.resolve(me);
                  };
                  superSyncMethod.apply(me, args);
                }
              }).fail(deferred.reject);
            }).fail(deferred.reject);
            return deferred.promise();
          }
          return superSyncMethod.apply(me, args);
        },

        getHomeCabineNode: function () {
          return {
            id: nodeUtils.getHomeCabinetId(),
            name: lang.homeCabinetNodeName,
            type: nodeUtils.getHomeCabinetType(),
            _is_home_cabinet: true
          };
        },

        getNodePath: function (breadCrumNodeCollection, nodePath ) {
          breadCrumNodeCollection.forEach(function (node) {
            if (node.id !== 'repository' && node.id !== this.node.get('id')) {
              nodePath.push(node.id);
            }
          }, this);
        },

        _fetchStartPathNode: function (config) {
          var me = this,
            deferred = $.Deferred(),
            startPathId = config.startingPath,
            context = Session.get().getContext(),
            nextNode = context.getModel(NextNodeModelFactory);

          // Fix for VE-4388710. When the required start path information is fetched by next node, then same information is used for start path.
          if (nextNode?.get('id') === startPathId && nextNode?.fetched === true) {
            me.startPathNode = {
              id: nextNode.get('id'),
              name: nextNode.get('name')
            };
            deferred.resolve();
          } else {
            $.ajax(this.connector.extendAjaxOptions({
              url: Url.combine(RestLinkrels.getLink(RestResources.getCurrentRepository().get('links'),
                  RestLinkrels.SELF), 'objects',startPathId),
              success: function (response) {
                me.startPathNode = {
                  id: response.properties.r_object_id,
                  name: response.properties.object_name
                };
                deferred.resolve();
              },
              error: function (xhr, status, error) {
                deferred.reject(utils.parseAjaxError(xhr, status, error));
              }
            }));
          }
          return deferred.promise();
        },

        _setRootForNode: function (config, pathIds) {
          var nodeId = this.node.get('id'),
            homeNode = this.getHomeCabineNode();

          // Check if it is one of the top level nodes
          if (pathIds[0] === constants.HiddenItems.ID) {
            var checkNodeType = {id: config.startingPath};
            nodeConverter.setNodeType(checkNodeType);
            if (checkNodeType.type === constants.Types.FOLDER || checkNodeType.type === constants.Types.CABINET || config.isDqlRoot) {
              this.root = {
                container: true,
                id: config.startingPath,
                name: config.objectName,
                type: checkNodeType.type
              };
            } else {
              var currRepo = RestResources.getCurrentRepository();
              this.root = {
                container: true,
                id: constants.NodeId.REPOSITORY,
                name: currRepo.get('description') || currRepo.get('name'),
                type: constants.Types.REPOSITORY
              };
            }
          } else if (nodeConverter.isNonDCTMNode(this.node)) {
            this.root = nodeUtils.createSpecialNode(nodeId);
            delete this.rootSubId;

          } else if (this.node.get('_is_home_cabinet') === true) {
            this.root = homeNode;
            delete this.rootSubId;

          } else { // Find out most appropriate root for the current node
            var pRoots = this.node.get('_possibleRoots') || {};

            // DTWO-120050 KLM Breadcrumbs for starting path bug fix
            // When drilling inside startpath folder or homecabinet the node might not have pRoots attribute => pRoots will be {}
            // In that case, if smartview has starting path and first entry in node navigation collection is the starting path => set pRoots.startPath = true
            if (!Object.prototype.hasOwnProperty.call(pRoots, 'startingPath')) {
              let nodeNavigationCollection = this.connector.context.getCollection(NodeNavigationCollctionFactory),
                  nodeNavigationCollectionFirst = nodeNavigationCollection?.at(0),
                  widgetStartPath = config.startingPath;

              if (widgetStartPath && (widgetStartPath === nodeNavigationCollectionFirst?.get('id') || nodeNavigationCollection.length === 0)) {
                pRoots.startingPath = true;
              }
            }

            pRoots.favoritesNodes = pRoots.favoritesNodes || [];

            if (!pRoots.startingPath && !nodeConverter.isDQLNode(this.root.id)) {
              this.root = nodeUtils.createSpecialNode(constants.NodeId.REPOSITORY);
              delete this.rootSubId;
            }
            // If node can be under current root, we don't do anything. Otherwise we try to find best matching root
            if (this.root.id !== constants.NodeId.REPOSITORY && !nodeConverter.isDQLNode(this.root.id)
              && (this.root.id || !pRoots.startingPath)
              && (!this.root._is_home_cabinet || !pRoots.homeCabinet)) {

              // Just ensure that sub-id is correctly set if it is favorites node
              if (this.root.id === constants.NodeId.FAVORITES && pRoots.favoritesNodes.length) {
                if (pRoots.favoritesNodes.indexOf(this.rootSubId) === -1) {
                  this.rootSubId = pRoots.favoritesNodes[0];
                }
              } else {
                // Node can't be under current root. So, we check if it should be under favorites, home cabinet or start path
                delete this.rootSubId;
                if (pRoots.favoritesNodes.length) {
                  this.root = nodeUtils.createSpecialNode(constants.NodeId.FAVORITES);
                  this.rootSubId = pRoots.favoritesNodes[0];
                } else if (pRoots.homeCabinet) {
                  this.root = homeNode;
                } else if (pRoots.startingPath) {
                  this.root = {};
                } else if (config.startingPath === constants.NodeId.REPOSITORY) {
                  this.root = nodeUtils.createSpecialNode(constants.NodeId.REPOSITORY);
                }
              }
            }

            // If user clicks on starting path after visiting favorites/home nodes, then remove root
            if (!config.treeEnabled && nodeId === config.startingPath && nodeId !== constants.NodeId.REPOSITORY) {
              this.root = {};
            }
          }
        },

        _resetRootForMobile: function (config, pathIds, pathNames) {
          //In Mobile, If there is a starting path then show path starting from that else show from repo
          if (this.root._is_home_cabinet && pathIds.indexOf(this.root.id) === -1) {
            //if it is home-cabinet then include that node in path
            pathIds.push(this.root.id);
            pathNames.push(this.root.name);
          }

          //If starting path is the repo/home cabinet then assign the root as repository
          if (this.rootSubId || this.root._is_home_cabinet || config.startingPath === constants.NodeId.REPOSITORY) {
            this.root = nodeUtils.createSpecialNode(constants.NodeId.REPOSITORY);
            delete this.rootSubId;
          } else {
            this.root = {};
          }

        }

      });

    }

  };

});
