csui.define('d2/overrides/nuc/models/actions',[
  'nuc/lib/underscore',
  'nuc/models/actions'
], function (_, ActionCollection) {
  'use strict';

  /**
   * D2 allows multiple actions with same signature (different payload). To support the same, use signature and menuId
   * combined as the unique identifier in the collection, but still support simple signature lookup in get method
   */
  _.extend(ActionCollection.prototype, {

    modelId: function (attrs) {
      var id = attrs.signature,
        data = attrs.commandData;
      if (data && data.menuId) {
        id = id + '_' + data.menuId;
      }
      return id;
    },

    get: function (obj) {
      if (obj == null) {
        return void 0;
      }

      var output = this._byId[obj];
      if (output) {
        return output;
      }

      if (this._isModel(obj)) {
        output = this._byId[this.modelId(obj.attributes)];
        if (output) {
          return output;
        }
      }

      output = this.findWhere(_.isObject(obj) ? obj : {signature: obj});
      if (output) {
        return output;
      }

      return obj.cid && this._byId[obj.cid];
    },

    findRecursively: function (id, menuId) {
      // search the terminal actions in the collection first
      var action = this.get({cid: id}) || this.find(function (item) {
        if (item.get('signature') === id) {
          if (menuId) {
            return item.get('commandData') && item.get('commandData').menuId === menuId;
          } else {
            return true;
          }
        }
      });
      // if not found, try all the submenus
      if (!action)
        // make an array of all action finding results produced
        // recursively and pick the first action found
      {
        action = _.find(this.map(function (item) {
          // if the submenu isn't empty handle it as another action
          // collection recursively - get the action or undefined
          // if it wasn't found
          return item.children.findRecursively(id);
          // pick the first action which is not undefined
        }), function (item) {
          return item;
        });
      }
      return action;
    }
  });

});
