csui.define('d2/overrides/csui/utils/commands/open.document',[
  'csui/utils/commands/open.document/open.document',
  'csui/utils/commandhelper'
], function (OpenDocumentCommand, CommandHelper) {
  'use strict';

  var oldEnabled = OpenDocumentCommand.prototype.enabled;

  OpenDocumentCommand.prototype.enabled = function (status/*, options*/) {
    var enabled = oldEnabled.apply(this, arguments),
      node = CommandHelper.getJustOneNode(status),
      permissions = node.get('basePermissions');

    return enabled && permissions && permissions.read === true && !status.nodes.find(node => !node.get('a_content_type'));
  };

});