csui.define('d2/models/mixins/expressions/expression',[
  'nuc/lib/underscore', 'dctmw/models/mixins/expressions/expression'
], function (_, DctmwExpressionModel) {


  var ExpressionModel = DctmwExpressionModel.extend({

    equals: function (val) {
      if (val instanceof ExpressionModel) {
        val = val.value;
      }

      //Mass update multiple values check preceeds attribute type
      if (val === '#####') {
        //If the array contains or has only one value which is '#####', it is said to be equal to multiple values
        return this.value === '#####' || _.contains(this.value, '#####');
      }
      return DctmwExpressionModel.prototype.equals.call(this, val);
    },

    isGreaterOrEqualsThan: function (val) {
      if (val instanceof ExpressionModel) {
        val = val.value;
      }

      //Mass update multiple values check preceeds attribute type
      if (this.value === '#####' && val === '#####') {
        return true;
      }

      return DctmwExpressionModel.prototype.isGreaterOrEqualsThan.call(this, val);
    },


    isLessOrEqualsThan: function (val) {
      if (val instanceof ExpressionModel) {
        val = val.value;
      }

      //Mass update multiple values check preceeds attribute type
      if (this.value === '#####' && val === '#####') {
        return true;
      }

      return DctmwExpressionModel.prototype.isLessOrEqualsThan.call(this, val);
    }
  });
  return ExpressionModel;
});
