csui.define('d2/overrides/csui/controls/tabletoolbar/tabletoolbar.view',[
  'csui/controls/tabletoolbar/tabletoolbar.view'
], function (TableToolbarView) {
  'use strict';

  TableToolbarView.prototype._updateAddToolbar = function () {
    var container = this.container;

    if (container) {
      // Enable newObject menu retrieval for the container, node.mixin.js uses this flag to do so.
      container._fetchMenuNewObjectItems = true;
    }
  };

});