csui.define('d2/controls/form/fields/d2passwordfield.view',['nuc/lib/underscore',
  'dctmw/controls/form/fields/dctmwpasswordfield.view'
], function (_, DctmwPasswordFieldView) {
  'use strict';

  var D2PasswordFieldView = DctmwPasswordFieldView.extend({

    constructor: function D2PasswordFieldView(/*options*/) {
      DctmwPasswordFieldView.prototype.constructor.apply(this, arguments);
    },

    getEditValue: function () {
      var val = DctmwPasswordFieldView.prototype.getEditValue.apply(this, arguments),
        model = this.options.model || this.model;

      if (model.get('options').massUpdateFileCount && _.isEmpty(val) && this.showMultiplePlaceholder) {
        val = this.ui.writeField.attr('placeholder');
      }

      return val;
    }

  });

  return D2PasswordFieldView;

});
