csui.define('d2/commands/d2-renditions',[
  "nuc/lib/jquery",
  "csui/models/command",
  "csui/utils/commandhelper",
  "i18n!d2/commands/nls/localized.strings",
  "dctmw/utils/client.location",
  'd2/utils/widget.constants',
  'dctmw/utils/rest.resources',
], function (
  $,
  CommandModel,
  CommandHelper,
  lang,
  clientLocation,
  widgetConstants,
  RestResources
) {
  "use strict";

  return CommandModel.extend({

    defaults: {
      signature: "D2-Renditions",
      command_key: "D2-Renditions",
      name: lang.CommandNameRenditions,
      verb: lang.CommandVerbRenditions,
      scope: "single",
    },

    enabled: function () {
      const userDefaultWidgets = RestResources.getCurrentUser().get('defaultWidgets');
      if(!userDefaultWidgets[widgetConstants.DEFAULT.RENDITIONS]){
        return false;
      }
      return CommandModel.prototype.enabled.apply(this, arguments);
    },

    execute: function (status) {
      let node = CommandHelper.getJustOneNode(status);
      clientLocation.navigate(
          clientLocation.modularizeFragment(
              // VE-OCTCR77IV4515268 Fix
              // Even though we were passing dropdown=renditions in the app url fragment,
              //      after navigating to metadata panel, this is getting cleared and user is shown the properties panel
              // Hence removed the dropdown value from the app url fragment and setting it in the done of return promise
              `#d2/nodes/${node.get('id')}/metadata/navigator`
          ),
          {trigger: true, reload: true}
      );

      // VE-OCTCR77IV4515268 Fix
      // Similar issue was seen in D2-Permissions command VE-OCTCR77IV3845128 (JIRA-DTWO-95912)
      // Setting {dropdown: rendition} viewStateModel state after navigating to metadata panel as fixed in D2-Permissions command
      return $.Deferred().resolve().promise().done(() => {
        status.context.viewStateModel.set(status.context.viewStateModel.CONSTANTS.STATE, {'dropdown': 'renditions'});
      });
    },

  });
});
