csui.define('d2/dialogs/target.browse/start.locations/related.files/related.files.factory',['nuc/lib/underscore', 'nuc/lib/jquery',
  'd2/dialogs/target.browse/start.locations/location.base.factory',
  'd2/dialogs/target.browse/start.locations/related.files/impl/related.files.collection'
], function (_, $, LocationBaseFactory, RelatedFilesCollection) {
  "use strict";

  var RelatedFilesFactory = LocationBaseFactory.extend({

    updateLocationModel: function (model) {
      model.set({
        hide: true,
        invalid: false
      });
      return $.Deferred().resolve().promise();
    },

    getLocationParameters: function (options) {
      var relatedFilesModel = {}, container = this.options.container;
      var relatedFiles = new RelatedFilesCollection(relatedFilesModel.models, _.extend({
        connector: options.connector
      }, {
        node: options.nodeModel,
        subTypeFilters: options.subTypeFilters,
        autofetch: true,
        autoreset: true,
        top: options.pageSize,
        showInTargetBrowse: true
      }));

      if (container) {
        container.set('unselectable', false);
      }
      return {
        container: container,
        collection: relatedFiles,
        locationName: ''
      };
    }
  });

  return RelatedFilesFactory;

});
