csui.define('d2/utils/contexts/factories/node.navigation',[
  'module',
  'nuc/lib/underscore',
  'nuc/lib/backbone',
  'csui/utils/contexts/factories/factory'
], function (module, _, Backbone, CollectionFactory) {
  'use strict';

  /*
     The Node Navigation Model Factory is added to address the link folder navigation issue.
     If a folder L1 is linked to 2 folders, while navigating we need to track the actual path selected so that the
     breadcrumb and tree show the correct path.
     While navigating from breadcrumb and tree we will reset the entire collection with the new path.
     While navigating using table we will add the node the existing path.
   */

  var NavigationModel = Backbone.Model.extend({
    constructor: function NavigationModel(attributes, options) {
      return Backbone.Model.prototype.constructor.call(this, attributes, options);
    }
  });


  var NavigationModelCollection = Backbone.Collection.extend({
    constructor: function NavigationModelCollection(/*attributes, options*/) {
      Backbone.Collection.prototype.constructor.apply(this, arguments);
    }
  });

  var NodeNavigationCollectionFactory = CollectionFactory.extend({
    propertyPrefix: 'nodeNavigation',

    constructor: function NavigationModelCollectionFactory(/*context, options*/) {
      CollectionFactory.prototype.constructor.apply(this, arguments);
      this.options.detached = true;
      this.options.permanent = true;
      var nextNodeNavigation = this.options.nextNodeNavigation || {};
      if (!(nextNodeNavigation instanceof Backbone.Collection)) {
        var config = module.config();
        nextNodeNavigation = new NavigationModelCollection(nextNodeNavigation.attributes || config.attributes,
          _.defaults({}, nextNodeNavigation.options, config.options));
      }
      this.property = nextNodeNavigation;
    },

    isFetchable: function () {
      return false;
    }
  });

  NodeNavigationCollectionFactory.defaultModel = NavigationModel;
  return NodeNavigationCollectionFactory;
});
