csui.define('d2/controls/globalmessage/globalmessage',['module',
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'nuc/lib/backbone',
  'nuc/lib/marionette',
  'csui/controls/node-type.icon/node-type.icon.view',
  'smart/controls/globalmessage/globalmessage',
  'smart/controls/progresspanel/progresspanel',
  'd2/controls/globalmessage/progresspanel.view.ext'
], function (module, $, _, Backbone, Marionette, NodeTypeIconView, SmartGlobalMessage, SmartProgressPanel, D2ProgressPanelView) {
  'use strict';
    var collectionUpdate = function (col) {
      col.forEach(function (model) {
        if (!!model.node && model.node.get('mime_type') === undefined) {
          model.node.set({
            container: false,
            type: model.node.get('type') !== undefined ?
              model.node.get('type') : model.get('type') !== undefined ?
                model.get('type') : 144,
            mime_type: model.get('mime_type') || model.get('type')
          }, {silent: true});
        }
        //For cases when new object is created, the property values are not yet saved and need to be extended to the model attributes
        var progressNode = new Backbone.Model(_.extend({}, model.node.attributes?.properties || {}, model.node.attributes));
        model.set('iconView', new NodeTypeIconView({node: progressNode}), {silent: true});
      });
    },
    GlobalMessage = _.extend(SmartGlobalMessage, {
      setProgresspanelMessageRegionView: _.bind(
        SmartProgressPanel.setProgresspanelMessageRegionView, SmartProgressPanel),
      setFileUploadCollection: _.bind(SmartProgressPanel.setFileUploadCollection,
        SmartProgressPanel),
      showFileUploadProgress: _.bind(SmartProgressPanel.showFileUploadProgress,
        SmartProgressPanel),
      hideFileUploadProgress: _.bind(SmartProgressPanel.hideFileUploadProgress,
        SmartProgressPanel),
      _showMessageView: _.bind(SmartGlobalMessage._showMessageDialogView,
        SmartGlobalMessage),
      showProgressPanel: function (collection, opts) {
        var enableCancel = opts.enableCancel !== undefined ? opts.enableCancel : true;
        var optns = _.extend(opts, {
            ProgressPanelview: D2ProgressPanelView,
            collection: collection,
            enableCancel: enableCancel,
            enableMinimiseButton: true,
            allowMultipleInstances: true,
          });

        if(opts.skipUnique !== true){
          optns.actionType = _.uniqueId(optns.actionType+'_');
        }

        $('.perspective-module-view').scrollTop(0);

        collectionUpdate(collection);

        SmartProgressPanel.showProgressPanel.call(SmartProgressPanel, optns.collection, optns);
        /*Since SVF code is not returning progress panel, D2SV keeps track of the progresspanel with type name.
        *The progress panel can be looked up with the action type name.
        */
        return optns.actionType;
      },
      isActionInProgress: _.bind(SmartProgressPanel.isActionInProgress, SmartProgressPanel),
      showPermissionApplyingProgress: _.bind(SmartProgressPanel.showPermissionApplyingProgress,
        SmartProgressPanel),
      showLoader: _.bind(SmartProgressPanel.showLoader, SmartProgressPanel),
      changeLoaderMessage: _.bind(SmartProgressPanel.changeLoaderMessage, SmartProgressPanel),
      cleanupPreviousMessagesForD2: _.bind(SmartGlobalMessage._cleanupPreviousMessageRegion, SmartGlobalMessage),
      hideProgressPanel: function () {
          console.warn('The use of the hideProgressPanel method is deprecated and should be avoided in future implementations.');
      }
    });

  return GlobalMessage;

});