csui.define('d2/controls/form/fields/alpaca/alpd2richtextfield',['module', 'nuc/lib/underscore', 'nuc/lib/jquery', 'nuc/lib/backbone',
  'nuc/lib/marionette', 'csui/lib/alpaca/js/alpaca.lite', 'csui/models/form',
  'd2/controls/form/fields/d2richtextfield.view'
], function (module, _, $, Backbone, Marionette, Alpaca, FormModel, D2RichTextFieldView) {

  Alpaca.Fields.D2RichTextField = Alpaca.Fields.TextAreaField.extend({

    constructor: function D2RichTextField(container, data, options, schema, view, connector, onError) {
      this.prepareOptionsAndSchema(options, schema);
      this.base(container, data, options, schema, view, connector, onError);
    },

    prepareOptionsAndSchema: function (options, schema) {
      //Setting Rich Text editor field as readonly and non-mandatory field in mass update use case.
      if (options.enableHtmlEditor && !!options.massUpdateFileCount) {
        schema.readonly = true;
        schema.required = false;
        options.disableExpand = true;
      }
      //Setting custom validator for HTML content.
      options.validator = this.htmlContentValidator.bind(this);
    },

    getFieldType: function () {
      return 'richtext';
    },

    postRender: function (callback) {
      this.base(callback);
      this.showField();
    },

    isValidationParticipant: function () {
      var result = this.base();
      return result && !this.schema.disabled;
    },

    isRequired: function () {
      var result = this.base();
      return result && !this.schema.disabled;
    },

    showField: function () {
      var id = this.id;
      this.options.id = "lbl" + _.uniqueId(id);

      // add an id to the <label> element like alpaca23Label
      var id4Label,
        labelElement = $(this.field[0]).find('label');

      if (labelElement && labelElement.length === 1) {
        id4Label = labelElement.attr('for') + "Label";
        labelElement.attr('id', id4Label);
      }

      this.fieldView = new D2RichTextFieldView({
        model: new Backbone.Model({
          data: this.data,
          options: this.options,
          schema: this.schema,
          id: id // <textarea>
        }),
        id: _.uniqueId(id), // wrapper <div>
        alpacaField: this,
        labelId: id4Label,
        value: this.data,
        readonly: true,
        dataId: this.name,
        path: this.path,
        alpaca: {
          data: this.data,
          options: this.options,
          schema: this.schema
        }
      });

      // replace alpaca control with empty div having same classes as control
      var $field = $('<div>').addClass('alpaca-control');
      this.getControlEl().replaceWith($field);

      // show our field in div
      this.region = new Marionette.Region({el: $field});
      this.region.show(this.fieldView);

      return;
    },

    focus: function () {
      this.fieldView.setFocus();
    },

    setValue: function (value) {
      value === null ? this.base('') : this.base(value);
    },

    getValue: function () {
      return this.fieldView ? this.fieldView.getValue() : this.data;
    },

    destroy: function () {
      this.base();
      if (this.region) {
        this.fieldView?.destroy();
        this.region.destroy();
      }
    },
    setValueAndValidate: function( value, validate) {
      this.setValue(value);
      var bIsValid = true;
      if( validate) {
        bIsValid = this.validate();
        this.refreshValidationState(false);
      }
      return bIsValid;
    },

    htmlContentValidator: function (callback) {
      if(this.fieldView){
        this.fieldView.validateHtmlContent.call(this.fieldView, callback);
      } else {
        callback({
          "status": true
        });
      }
    }

  });

  Alpaca.registerFieldClass('richtext', Alpaca.Fields.D2RichTextField, 'bootstrap-csui');
  return Alpaca.Fields.D2RichTextField;
});