csui.define('d2/models/workflow/tasks.client.columns',[
  'nuc/lib/underscore',
  'nuc/lib/backbone',
  'i18n!csui/models/widget/nls/lang'
], function (_, Backbone, lang) {
  'use strict';

  var TasksColumnModel = Backbone.Model.extend({
    idAttribute: null,

    constructor: function TasksColumnModel(attributes, options) {
      if (attributes && !attributes.title) {
        attributes.title = lang[attributes.column_key];
      }
      Backbone.Model.prototype.constructor.call(this, attributes, options);
    }
  });

  return Backbone.Collection.extend({
    model: TasksColumnModel,

    resetTasksCollection: function (response, options) {
      var columns;
      if (response && response.columns) {
        // columns from server
        columns = _.map(response.columns, function (column) {
          return new TasksColumnModel(column);
        });
      }
      this.reset(columns, options);
      this.fetched = true;
    }
  });

});
