csui.define('d2/controls/form/fields/listfieldview/d2listfieldoptionsitem.view',[
  'nuc/lib/underscore',
  'd2/utils/mass.update.utils',
  'dctmw/controls/form/fields/listfieldview/dctmwlistfieldoptionsitem.view'
], function (_, MassUpdateUtils, DctmwListFieldOptionsItem) {
  'use strict';
  return DctmwListFieldOptionsItem.extend({
    constructor: function D2ListFieldSelectionItemView(options) {
      DctmwListFieldOptionsItem.prototype.constructor.call(this, options);
    },
    className: function () {
      return _.result(DctmwListFieldOptionsItem.prototype, 'className') + ' d2-selectedList';
    },
    onRender: function () {
      DctmwListFieldOptionsItem.prototype.onRender.call(this);
      if (this.options.parentView.options.parentView.model.get('options').massUpdateFileCount
        && MassUpdateUtils.fieldHasMultipleValues(this.model.get('id'))
      ) {
        this.$el.hide();
      }
    }
  });
});